# Code snippet to check for potential security vulnerabilities in file handling
import os

def check_file_accessibility(file_path):
    # Check if the file exists and is accessible
    if os.path.isfile(file_path):
        print(f"File {file_path} is accessible.")
    else:
        print(f"File {file_path} is not accessible or does not exist.")

# Example usage
check_file_accessibility('/data/somefile.txt')
